-- Re-check provider subscription at the exact moment of accepting a request or sending a large-vehicle offer.
CREATE OR REPLACE FUNCTION public.accept_service_request(_request_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE r public.service_requests%ROWTYPE; v_customer uuid; v_updated integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF; IF NOT ( public.has_role(auth.uid(), 'driver') OR public.has_role(auth.uid(), 'worker') ) THEN RAISE EXCEPTION 'provider_role_required'; END IF; IF NOT public.mamnoon_provider_subscription_active(auth.uid()) THEN RAISE EXCEPTION 'subscription_required'; END IF; IF EXISTS ( SELECT 1 FROM public.user_blocks b WHERE b.user_id = auth.uid() AND (b.expires_at IS NULL OR b.expires_at > now()) ) THEN RAISE EXCEPTION 'user_blocked'; END IF; -- Check temporary suspension for taxi drivers and workers.
IF EXISTS ( SELECT 1 FROM public.driver_profiles dp WHERE dp.user_id = auth.uid() AND dp.suspended_until IS NOT NULL AND dp.suspended_until > now() ) OR EXISTS ( SELECT 1 FROM public.worker_profiles wp WHERE wp.user_id = auth.uid() AND wp.suspended_until IS NOT NULL AND wp.suspended_until > now() ) THEN RAISE EXCEPTION 'provider_temporarily_suspended'; END IF; SELECT * INTO r FROM public.service_requests WHERE id = _request_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'request_unavailable'; END IF; PERFORM 1 FROM public.request_offers o WHERE o.request_id = _request_id AND o.provider_id = auth.uid() AND o.status = 'pending' AND o.expires_at > now() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'request_offer_expired'; END IF; -- Serialize provider acceptance across all request types.
PERFORM pg_advisory_xact_lock(91840060); IF EXISTS ( SELECT 1 FROM public.service_requests WHERE provider_id = auth.uid() AND status IN ('accepted', 'in_progress') ) THEN RAISE EXCEPTION 'لديك طلب نشط بالفعل'; END IF; UPDATE public.service_requests SET provider_id = auth.uid(), status = 'accepted', accepted_at = now() WHERE id = _request_id AND status IN ('pending', 'searching') AND provider_id IS NULL AND ( ( type = 'taxi' AND vehicle_category::text IS DISTINCT FROM 'large' AND public.has_role(auth.uid(), 'driver') AND EXISTS ( SELECT 1 FROM public.driver_profiles dp WHERE dp.user_id = auth.uid() AND dp.vehicle_category = service_requests.vehicle_category AND dp.vehicle_category::text IN ('economy', 'premium', 'luxury') AND dp.status = 'approved' AND dp.available = true AND ( dp.suspended_until IS NULL OR dp.suspended_until <= now() ) ) ) OR ( type = 'service' AND public.has_role(auth.uid(), 'worker') AND EXISTS ( SELECT 1 FROM public.worker_profiles wp WHERE wp.user_id = auth.uid() AND wp.status = 'approved' AND wp.available = true AND ( wp.suspended_until IS NULL OR wp.suspended_until <= now() ) ) AND ( service_id IS NULL OR EXISTS ( SELECT 1 FROM public.worker_services ws WHERE ws.worker_id = auth.uid() AND ws.service_id = service_requests.service_id ) ) ) ) RETURNING customer_id INTO v_customer; GET DIAGNOSTICS v_updated = ROW_COUNT; IF v_updated = 0 THEN RAISE EXCEPTION 'request_unavailable'; END IF; INSERT INTO public.chats(request_id, customer_id, provider_id) VALUES (_request_id, v_customer, auth.uid()) ON CONFLICT (request_id) DO UPDATE SET provider_id = EXCLUDED.provider_id, updated_at = now(); UPDATE public.request_offers SET status = CASE WHEN provider_id = auth.uid() THEN 'accepted' ELSE 'cancelled' END, responded_at = now() WHERE request_id = _request_id AND status = 'pending'; INSERT INTO public.notifications(user_id, type, title, body, link, data) VALUES ( v_customer, 'request_accepted', 'تم قبول طلبك', 'مقدّم الخدمة قبل طلبك ويمكنك متابعة التفاصيل الآن.', '/request/' || _request_id, jsonb_build_object( 'request_id', _request_id, 'provider_id', auth.uid() ) ); RETURN true; END; $function$;
CREATE OR REPLACE FUNCTION public.submit_large_vehicle_offer(_request_id uuid, _price integer, _message text DEFAULT NULL::text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE r public.service_requests%ROWTYPE; v_offer uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'large_driver') THEN RAISE EXCEPTION 'large_driver_role_required'; END IF; IF NOT public.mamnoon_provider_subscription_active(auth.uid()) THEN RAISE EXCEPTION 'subscription_required'; END IF; IF _price IS NULL OR _price < 250 OR _price > 50000 OR _price % 250 <> 0 THEN RAISE EXCEPTION 'invalid_offer_price'; END IF; IF EXISTS ( SELECT 1 FROM public.user_blocks b WHERE b.user_id = auth.uid() AND (b.expires_at IS NULL OR b.expires_at > now()) ) THEN RAISE EXCEPTION 'user_blocked'; END IF; SELECT * INTO r FROM public.service_requests WHERE id = _request_id FOR UPDATE; IF NOT FOUND OR r.type::text <> 'taxi' OR r.vehicle_category::text <> 'large' OR r.status::text NOT IN ('pending','searching') OR r.provider_id IS NOT NULL THEN RAISE EXCEPTION 'request_unavailable'; END IF; IF r.customer_id = auth.uid() THEN RAISE EXCEPTION 'cannot_offer_on_own_request'; END IF; IF NOT EXISTS ( SELECT 1 FROM public.driver_profiles dp WHERE dp.user_id = auth.uid() AND dp.available = true AND dp.status = 'approved' AND dp.vehicle_category::text = 'large' AND ( r.vehicle_type IS NULL OR dp.vehicle_type = r.vehicle_type ) ) THEN RAISE EXCEPTION 'driver_vehicle_not_eligible'; END IF; IF EXISTS ( SELECT 1 FROM public.service_requests sr WHERE sr.provider_id = auth.uid() AND sr.status::text IN ('accepted','in_progress') ) THEN RAISE EXCEPTION 'provider_has_active_request'; END IF; UPDATE public.request_offers SET proposed_price = _price, offer_message = NULLIF( LEFT(TRIM(COALESCE(_message, '')), 500), '' ), status = 'pending', sent_at = now(), expires_at = now() + interval '24 hours', responded_at = NULL WHERE request_id = _request_id AND provider_id = auth.uid() AND status IN ('pending','rejected') AND expires_at > now() RETURNING id INTO v_offer; IF v_offer IS NULL THEN RAISE EXCEPTION 'request_offer_expired'; END IF; INSERT INTO public.notifications ( user_id, type, title, body, link, data ) VALUES ( r.customer_id, 'large_vehicle_price_offer', 'عرض سعر لسيارتك الكبيرة', 'أرسل صاحب سيارة عرضاً بقيمة ' || _price::text || ' دينار.', '/request/' || r.id::text, jsonb_build_object( 'request_id', r.id, 'offer_id', v_offer, 'price_iqd', _price ) ); RETURN v_offer; END; $function$;
